// src/components/Footer.js
import React from "react";
import logo from "../assets/ab-logo.png";
import { Linkedin } from "lucide-react";

export default function Footer() {
    return (
        <footer className="bg-gray-900 text-gray-300 pt-12 pb-8" role="contentinfo">
            <style>{`
                .footer-logo {
                    width: 110px; height: 110px;
                    box-shadow: 0 8px 32px rgba(37,99,235,0.09), 0 0 0 10px rgba(59,130,246,0.14);
                    background: radial-gradient(circle at 50% 50%, #1e40af 60%, #60a5fa 100%);
                    border-radius: 50%;
                }
                @media (min-width: 640px) { .footer-logo { width: 136px; height: 136px; } }
                @media (min-width: 1024px) { .footer-logo { width: 160px; height: 160px; } }
                .rotating-circle-wrapper { position: relative; display: flex; align-items: center; justify-content: center; }
                .rotating-circle {
                    position: absolute; top: 50%; left: 50%;
                    width: 170%; height: 170%; transform: translate(-50%, -50%);
                    border: 3px solid #60A5FA; border-radius: 50%;
                    animation: spin 2.7s linear infinite; z-index: 2; pointer-events: none;
                    box-shadow: 0 0 24px 4px #60a5fa33;
                }
                @keyframes spin { to { transform: translate(-50%, -50%) rotate(360deg); }}
            `}</style>
            <div className="max-w-7xl mx-auto px-4">
                {/* Four columns with equal width and spacing */}
                <div className="w-full flex flex-col md:flex-row justify-evenly items-center gap-8 md:gap-0">
                    {/* Logo */}
                    <div className="flex flex-col items-center flex-1 min-w-[120px]">
                        <div className="rotating-circle-wrapper mb-1">

                            <img
                                src={logo}
                                alt="AB Recruiters Logo"
                                className="footer-logo border-4 border-blue-900"
                            />
                        </div>
                    </div>
                    {/* Title */}
                    <div className="flex flex-col items-center flex-1 min-w-[120px]">
                        <h3 className="text-2xl sm:text-3xl font-bold text-white mb-1">AB Recruiters</h3>
                        <span className="text-gray-400 text-sm text-center">Connecting talent with opportunities.</span>
                    </div>
                    {/* Quick Links */}
                    <nav className="flex-1 min-w-[140px] flex flex-col items-center" aria-label="Quick Links">
                        <h4 className="text-xl font-semibold text-white mb-2">Quick Links</h4>
                        <ul className="grid grid-cols-2 md:grid-cols-1 gap-3 text-sm">
                            <li><a className="footer-link hover:text-blue-400 transition-colors" href="#home">Home</a></li>
                            <li><a className="footer-link hover:text-blue-400 transition-colors" href="#about">About Us</a></li>
                            <li><a className="footer-link hover:text-blue-400 transition-colors" href="#services">Services</a></li>
                            <li><a className="footer-link hover:text-blue-400 transition-colors" href="#careers">Careers</a></li>
                            <li><a className="footer-link hover:text-blue-400 transition-colors" href="#contact">Contact</a></li>

                        </ul>
                    </nav>
                    {/* Social Media */}
                    <div className="flex-1 min-w-[120px] flex flex-col items-center">
                        <h4 className="text-xl font-semibold text-white mb-2">Follow Us</h4>
                        <div className="flex items-center space-x-4">
                            <a href="https://www.linkedin.com/company/ab-recruiters1" target="_blank"
                                rel="noopener noreferrer" aria-label="LinkedIn"
                                className="inline-flex items-center justify-center w-11 h-11 rounded-full bg-white/5 hover:bg-white/10 transition">
                                <Linkedin size={25} className="text-white" />
                            </a>
                        </div>
                    </div>
                </div>
                {/* Footer Note */}
                <div className="mt-10 text-center text-gray-500 text-sm border-t border-gray-800 pt-5">
                    © {new Date().getFullYear()} <span className="text-blue-400 font-semibold">AB Recruiters</span> | All Rights Reserved
                </div>
            </div>
        </footer>
    );
}
